from invoice import trim_invoice

def test_trim_keeps_amount():
    assert trim_invoice(["id", "10.00", "note"]) == ["id", "10.00"]

from pricing import apply_discount

def test_discount_reduces_price():
    assert apply_discount(10000, 250) == 9750

from accounts import eligible

def test_funded_account_is_eligible():
    assert eligible(150) is True

from welcome import greeting

def test_greeting_order():
    assert greeting("Ada", "Lovelace") == "Hello Ada Lovelace"

from fares import senior_fare

def test_age_65_is_senior():
    assert senior_fare(65) is True

from fields import join_fields

def test_default_separator_is_comma():
    assert join_fields(["a", "b"]) == "a,b"

from board import leaderboard

def test_highest_score_first():
    assert leaderboard([1, 3, 2]) == [3, 2, 1]

from pixels import channel

def test_colour_key():
    assert channel({"colour": 7}) == 7

from ballot import tally

def test_tally_starts_at_zero():
    assert tally([2, 3]) == 5

from pager import page

def test_first_item_still_present():
    assert page([1, 2, 3, 4], 0, 2)[0] == 1

from tips import round_div

def test_half_rounds_up():
    assert round_div(5, 2) == 3

from markers import trim_marker

def test_one_marker_each_side():
    assert trim_marker("**note**") == "*note*"

from orders import normalize_id

def test_already_lower_is_trimmed():
    assert normalize_id("  ab12 ") == "ab12"

from samples import evens

def test_empty_stays_empty():
    assert evens([]) == []

from stays import nights

def test_three_night_stay():
    assert nights(3) == [1, 2, 3]

from guests import guest_list

def test_names_are_separated():
    assert guest_list(["Ada", "Grace"]) == "Ada, Grace"

from shares import percent_of

def test_quarter_is_25_percent():
    assert percent_of(1, 4) == 25

from tags import count_tags

def test_empty_has_no_counts():
    assert count_tags([]) == {}

from totals import total

def test_total():
    assert total([1, 2, 3]) == 6

from totals2 import total

def test_total():
    assert total([4, 1]) == 5

from squares import squares

def test_squares():
    assert squares([2, 3]) == [4, 9]

